UNITS = [{'id': 'PEDS-U049', 'ch': 6, 'n': 49, 'title': 'Temperature Regulation', 'sec': 'Temperature Regulation · p25', 'guide': 'Normal temperature 36.5–37.5°C (roof of dry axilla, electronic thermometer). Heat loss: radiation (major), convection (air flow), evaporation (via sweat), conduction; head = major site (large surface area). Heat production: ↑ physical activity & brown fat non-shivering thermogenesis (nape of neck m/c, interscapular, perirenal) via uncoupling of oxidative phosphorylation → hypothalamus stress → ↑ noradrenaline → ↑ β-oxidation → heat, brown fat ↑ mitochondria. (Book p25)', 'qs': ['PEDS-C6-001', 'PEDS-C6-002', 'PEDS-C6-003', 'PEDS-C6-004', 'PEDS-C6-005', 'PEDS-C6-006', 'PEDS-C6-007', 'PEDS-C6-008', 'PEDS-C6-009', 'PEDS-C6-010', 'PEDS-C6-011', 'PEDS-C6-012', 'PEDS-C6-013', 'PEDS-C6-014', 'PEDS-C6-015', 'PEDS-C6-016', 'PEDS-C6-017', 'PEDS-C6-018', 'PEDS-C6-019', 'PEDS-C6-020', 'PEDS-C6-021', 'PEDS-C6-022', 'PEDS-C6-023', 'PEDS-C6-024', 'PEDS-C6-025']}, {'id': 'PEDS-U050', 'ch': 6, 'n': 50, 'title': 'Hypothermia: Classification', 'sec': 'Hypothermia · p25', 'guide': 'Cold stress 36.4–36°C (cold extremities, warm body), moderate hypothermia 36–32°C, severe <32°C; hyperthermia >37.5°C. Prevention of hypothermia is a critical aspect of newborn care. (Book p25)', 'qs': ['PEDS-C6-026', 'PEDS-C6-027', 'PEDS-C6-028', 'PEDS-C6-029', 'PEDS-C6-030', 'PEDS-C6-031']}, {'id': 'PEDS-U051', 'ch': 6, 'n': 51, 'title': 'Prevention of Hypothermia — Stable Baby (KMC)', 'sec': 'Prevention of Hypothermia · p25', 'guide': 'In hemodynamically stable baby: 1. Cover head to toe; 2. Kangaroo mother care (KMC) for LBW/preterm, nutrition breastfeed, duration as long as possible, mother can nap in semi-recumbent 30° elevation, avoid <1 hr sessions (repeated handling → stress), stop once ≥2.5 kg or at 37 wks. KMC: turn head to one side, baby close to mother, skin-to-skin by conduction; position upright, frog-leg flexed. (Book p25)', 'qs': ['PEDS-C6-032', 'PEDS-C6-033', 'PEDS-C6-034', 'PEDS-C6-035', 'PEDS-C6-036', 'PEDS-C6-037', 'PEDS-C6-038', 'PEDS-C6-039', 'PEDS-C6-040', 'PEDS-C6-041', 'PEDS-C6-042', 'PEDS-C6-043', 'PEDS-C6-044', 'PEDS-C6-045', 'PEDS-C6-046']}, {'id': 'PEDS-U052', 'ch': 6, 'n': 52, 'title': 'Prevention of Hypothermia — Unstable Baby (NICU)', 'sec': 'Prevention of Hypothermia · p26', 'guide': 'In hemodynamically unstable baby placed in NICU: 1. Overhead radiant warmer = open source, heat by radiation, modes manual vs auto/servo (preferred); 2. Incubator = closed/covered source of heat. (Book p26)', 'qs': ['PEDS-C6-047', 'PEDS-C6-048', 'PEDS-C6-049', 'PEDS-C6-050', 'PEDS-C6-051', 'PEDS-C6-052', 'PEDS-C6-053']}, {'id': 'PEDS-U053', 'ch': 6, 'n': 53, 'title': 'Neonatal Hypoglycemia: Definition, Screening & Risk Factors', 'sec': 'Neonatal Hypoglycemia · p27', 'guide': 'Hypoglycemia = blood glucose <45 mg/dL. Can be asymptomatic yet dangerous → screen (heel prick, routine newborn care). Risk factors: inadequate substrate (SGA <3rd percentile, preterm <35 wks), relative hyperinsulinemia (LGA, IDM), sick neonates (sepsis, birth asphyxia, severe hypothermia). High-risk period first 72 hrs. (Book p27)', 'qs': ['PEDS-C6-054', 'PEDS-C6-055', 'PEDS-C6-056', 'PEDS-C6-057', 'PEDS-C6-058', 'PEDS-C6-059', 'PEDS-C6-060', 'PEDS-C6-061', 'PEDS-C6-062', 'PEDS-C6-063', 'PEDS-C6-064', 'PEDS-C6-065', 'PEDS-C6-066']}, {'id': 'PEDS-U054', 'ch': 6, 'n': 54, 'title': 'Hypoglycemia: Manifestations & Management', 'sec': 'Neonatal Hypoglycemia · p27', 'guide': '1. Asymptomatic; 2. Symptomatic: jitteriness/tremors m/c & earliest (stops with stimulus), seizure not stimulus-sensitive, lethargy, refusal of feeds, autonomic symptoms uncommon. Management: symptomatic IV 2 mL/kg 10% dextrose → continuous infusion GIR 6 mg/kg/min ↑ by 2 mg/kg/min → 12 mg/kg/min; asymptomatic <40 mg/dL start infusion, 40–45 mg/dL trial of oral breastfeeds → reassess after 20–30 min. (Book p27)', 'qs': ['PEDS-C6-067', 'PEDS-C6-068', 'PEDS-C6-069', 'PEDS-C6-070', 'PEDS-C6-071', 'PEDS-C6-072', 'PEDS-C6-073', 'PEDS-C6-074', 'PEDS-C6-075', 'PEDS-C6-076', 'PEDS-C6-077', 'PEDS-C6-078', 'PEDS-C6-079', 'PEDS-C6-080', 'PEDS-C6-081']}, {'id': 'PEDS-U055', 'ch': 6, 'n': 55, 'title': 'Resistant Hypoglycemia', 'sec': 'Resistant Hypoglycemia · p28', 'guide': 'Resistant = GIR >12 mg/kg/min or persists >7 days. Causes: hypopituitarism (↓ ACTH), metabolic (glycogen storage, galactosemia), nesidioblastosis (β-islet hyperplasia → congenital hypoglycemia). Treatment: stimulate gluconeogenesis (hydrocortisone, glucagon) & ↓ insulin (diazoxide, octreotide); avoid diazoxide/glucagon in SGA babies. (Book p28)', 'qs': ['PEDS-C6-082', 'PEDS-C6-083', 'PEDS-C6-084', 'PEDS-C6-085', 'PEDS-C6-086', 'PEDS-C6-087', 'PEDS-C6-088', 'PEDS-C6-089', 'PEDS-C6-090', 'PEDS-C6-091']}, {'id': 'PEDS-U056', 'ch': 6, 'n': 56, 'title': 'Infant of Diabetic Mother (IDM)', 'sec': 'Infant of Diabetic Mother · p28', 'guide': "Pedersen's hypothesis: maternal hyperglycemia ↑ glucose → placenta → fetus ↑ insulin → anabolism & growth → LGA. Effects of ↑ insulin: asymmetric septal hypertrophy (resolves when insulin ↓), inactivation of surfactant → alveoli collapse → RDS, lazy left colon (↓ gut motility → delayed meconium). LGA side effect: ↑ O2 → ↑ RBC/polycythemia → hyperviscosity → thromboembolism. Congenital anomalies if hyperglycemia in 1st trimester (embryogenesis): cardiac m/c VSD, most specific TGA; CNS m/c NTD, most specific caudal regression (lumbosacral agenesis). Metabolic: ↑ insulin → ↓ PTH → functional hypoparathyroidism → hypocalcemia <8 mg/dL & hypomagnesemia <1.5 mg/dL; hypoglycemia m/c cause of seizure (> hypocalcemia). (Book p28-29)", 'qs': ['PEDS-C6-092', 'PEDS-C6-093', 'PEDS-C6-094', 'PEDS-C6-095', 'PEDS-C6-096', 'PEDS-C6-097', 'PEDS-C6-098', 'PEDS-C6-099', 'PEDS-C6-100', 'PEDS-C6-101', 'PEDS-C6-102', 'PEDS-C6-103', 'PEDS-C6-104', 'PEDS-C6-105', 'PEDS-C6-106', 'PEDS-C6-107', 'PEDS-C6-108', 'PEDS-C6-109', 'PEDS-C6-110', 'PEDS-C6-111', 'PEDS-C6-112', 'PEDS-C6-113', 'PEDS-C6-114']}]
